<template><div class="grid"><div class="glass panel"><div class="panel-top"><h3>{{item.id?'IELTS material tahrirlash':'Yangi IELTS material'}}</h3><button v-if="item.id" class="link-btn" @click="reset">Bekor qilish</button></div><p class="help" v-if="mode==='reading' || mode==='ieltsListening'">Savollar: <code>{{mode==='reading'?'type | savol | variant1 | variant2 | variant3 | to‘g‘ri':'savol | variant1 | variant2 | variant3 | to‘g‘ri'}}</code></p><form @submit.prevent="$emit('save',{...item})">
<div v-if="mode==='reading'"><label>Title<input v-model.trim="item.title" required></label><label>Passage<textarea v-model="item.text" rows="12" required></textarea></label><label>Questions<textarea v-model="item.questionsRaw" rows="10"></textarea></label></div>
<div v-else-if="mode==='ieltsListening'"><label>Context<input v-model.trim="item.context" placeholder="A student is asking..." required></label><label>Script<textarea v-model="item.script" rows="10" required></textarea></label><label>Questions<textarea v-model="item.questionsRaw" rows="10"></textarea></label></div>
<div v-else-if="mode==='task1'"><label>Title<input v-model.trim="item.title" required></label><label>Instruction<textarea v-model="item.instruction" rows="5" required></textarea></label><label>Columns (har qatorda bitta)<textarea v-model="item.columnsRaw" rows="4" required></textarea></label><label>Rows (<code>|</code> bilan ajrating)<textarea v-model="item.rowsRaw" rows="7" required></textarea></label></div>
<div v-else-if="mode==='task2'"><label>Essay prompt<textarea v-model="item.prompt" rows="10" required></textarea></label></div>
<div v-else><div class="row"><label>Title<input v-model.trim="item.title" required></label><label>Part 2 cue<input v-model.trim="item.cue" required></label></div><label>Part 1 savollar<textarea v-model="item.part1Raw" rows="6"/></label><label>Part 2 points<textarea v-model="item.pointsRaw" rows="5" placeholder="Where it is\nWhy you want to go"></textarea></label><label>Part 3 savollar<textarea v-model="item.part3Raw" rows="6"/></label></div>
<button class="primary" :disabled="saving">{{saving?'Saqlanmoqda…':item.id?'Saqlash':'IELTS qo‘shish'}}</button></form></div><div class="glass panel"><div class="panel-top"><h3>{{label}} <span>{{items.length}}</span></h3></div><div v-if="!items.length" class="empty">Hali custom material yo‘q.</div><div v-for="x in items" :key="x.id" class="item"><div><b>{{displayTitle(x.item)}}</b><span>{{summary(x.item)}}</span></div><div class="actions"><button @click="$emit('edit',x)"><i class="ti ti-pencil"></i></button><button class="danger" @click="$emit('delete',x.id)"><i class="ti ti-trash"></i></button></div></div></div></div></template>
<script setup>import {computed,ref,watch} from 'vue';const props=defineProps({mode:String,items:Array,initial:Object,saving:Boolean});const emit=defineEmits(['save','edit','delete']);const item=ref({...props.initial});watch(()=>props.initial,v=>item.value={...v},{deep:true});const label=computed(()=>({reading:'Custom Reading',ieltsListening:'Custom Listening',task1:'Custom Task 1',task2:'Custom Task 2',speaking:'Custom Speaking'}[props.mode]));function reset(){item.value=props.mode==='reading'?{id:'',title:'',text:'',questionsRaw:''}:props.mode==='ieltsListening'?{id:'',context:'',script:'',questionsRaw:''}:props.mode==='task1'?{id:'',title:'',instruction:'',columnsRaw:'',rowsRaw:''}:props.mode==='task2'?{id:'',prompt:''}:{id:'',title:'',part1Raw:'',cue:'',pointsRaw:'',part3Raw:''}}function displayTitle(x){return x?.title||x?.prompt||x?.context||'IELTS material'}function summary(x){return x?.questions?.length?`${x.questions.length} savol`:x?.part1?.length?`${x.part1.length} + Part 3`:x?.instruction?'Table task':'Custom material'}</script><style scoped>@import './editor.css';</style>
